<script setup lang="ts">
// FR-STANDARD-001/002; D18-API-015/016/017/053/054/055/060; TC-STANDARD-001..004
import {ref,reactive,onMounted} from 'vue';import {useAuthStore} from '../../stores/auth';import {get,command,errorText,type Page,type Row} from '../../api/implemented';import {type Standard,type Snapshot,versionStates,constraintsForm,constraintsBody,fillConstraints} from '../../api/governance';import ConstraintsForm from '../../components/ConstraintsForm.vue';
const auth=useAuthStore(),send=command(),rows=ref<Standard[]>([]),orgs=ref<Row[]>([]),assets=ref<Row[]>([]),fields=ref<Row[]>([]),asset=ref<Row|null>(null),selected=ref<Standard|null>(null),editing=ref<Snapshot|null>(null),error=ref(''),message=ref(''),busy=ref(false),page=ref(1),total=ref(0),keyword=ref('');
const identity=reactive({orgId:auth.user?.orgId||'',code:'',name:''}),form=reactive({versionNo:1,description:'',reason:''}),constraints=reactive(constraintsForm()),bind=reactive({assetId:'',fieldId:'',standardVersionId:'',reason:''});
async function load(){const p=await get<Page>('D18-API-015',{}, {page:String(page.value),size:'20',...(keyword.value?{keyword:keyword.value}:{})});rows.value=p.items as Standard[];total.value=p.total;if(selected.value)selected.value=await get<Standard>('D18-API-054',{id:selected.value.id})}
async function run(f:()=>Promise<unknown>){busy.value=true;error.value='';message.value='';try{await f();await load()}catch(e){error.value=errorText(e)}finally{busy.value=false}}
function newVersion(){editing.value=null;form.versionNo=(selected.value?.versions[0]?.versionNo||0)+1;form.description='';form.reason='';Object.assign(constraints,constraintsForm())}
function closeDetail(){selected.value=null;editing.value=null}
async function select(s:Standard){selected.value=await get<Standard>('D18-API-054',{id:s.id});newVersion();bind.standardVersionId='';assets.value=auth.permissions.includes('asset:read')?(await get<Page>('D18-API-010',{}, {orgId:s.orgId,size:'100'})).items:[];bind.assetId='';fields.value=[]}
function edit(v:Snapshot){editing.value=v;form.description=v.definition?.description||'';form.reason='';fillConstraints(constraints,v.definition?.constraints||{})}
async function saveVersion(){if(!selected.value)return;const definition={description:form.description,constraints:constraintsBody(constraints)};if(editing.value)await send('D18-API-055',{id:editing.value.id},{definition,expectedVersion:editing.value.version,reason:form.reason});else await send('D18-API-016',{id:selected.value.id},{versionNo:form.versionNo,expectedVersion:selected.value.version,definition});await load();newVersion();message.value='标准草稿已保存'}
async function publish(v:Snapshot){const reason=form.reason;if(!reason.trim())throw new Error('请先填写发布说明');await send('D18-API-017',{id:v.id},{expectedVersion:v.version,reason});editing.value=null;message.value='标准快照已发布，后续修改请创建新版本'}
async function assetChanged(){bind.fieldId='';if(!bind.assetId){fields.value=[];asset.value=null;return}asset.value=await get<Row>('D18-API-012',{id:bind.assetId});fields.value=await get<Row[]>('D18-API-013',{id:bind.assetId})}
async function binding(){if(!asset.value)return;await send('D18-API-060',{id:bind.fieldId},{standardVersionId:bind.standardVersionId,expectedAssetVersion:asset.value.version,reason:bind.reason});await assetChanged();message.value='发布标准版本已关联到资产字段'}
onMounted(()=>{window.addEventListener('datagov:close-detail',closeDetail);run(async()=>{await load();if(auth.permissions.includes('auth:read'))orgs.value=await get<Row[]>('D18-API-005')})});
</script>
<template><section><h2>数据标准</h2><p>维护结构化标准约束、发布版本及字段关联。已发布快照保留历史，不可直接修改。</p><p class="error" role="alert">{{error}}</p><p role="status">{{message}}</p><form class="actions" @submit.prevent="page=1;run(load)"><label>标准代码<input v-model="keyword" maxlength="64"></label><button :disabled="busy">查询</button></form><form v-if="auth.permissions.includes('standard:write')" @submit.prevent="run(async()=>{const s=await send<Standard>('D18-API-053',{},identity);identity.code='';identity.name='';await select(s)})"><h3>新增标准</h3><div class="columns"><label>所属组织<select v-model="identity.orgId"><option v-for="o in orgs" :key="o.id" :value="o.id">{{o.name}}</option><option v-if="!orgs.length" :value="identity.orgId">当前组织</option></select></label><label>标准代码<input v-model="identity.code" required maxlength="64" pattern="[A-Za-z][A-Za-z0-9_.-]*"></label><label>标准名称<input v-model="identity.name" required maxlength="128"></label></div><button :disabled="busy">创建</button></form><table><thead><tr><th>代码</th><th>名称</th><th>版本数</th><th>操作</th></tr></thead><tbody><tr v-for="s in rows" :key="s.id"><td>{{s.code}}</td><td>{{s.name}}</td><td>{{s.versions.length}}</td><td><button @click="run(()=>select(s))">查看版本</button></td></tr></tbody></table><p v-if="!rows.length">暂无数据标准。</p><div class="actions"><button :disabled="page<=1||busy" @click="page--;run(load)">上一页</button>第{{page}}页 · 共{{total}}项<button :disabled="page*20>=total||busy" @click="page++;run(load)">下一页</button></div><div v-if="selected"><h3>{{selected.name}} 的版本</h3><table><thead><tr><th>业务版本</th><th>状态</th><th>说明</th><th>操作</th></tr></thead><tbody><tr v-for="v in selected.versions" :key="v.id"><td>V{{v.versionNo}}</td><td>{{versionStates[v.status]}}</td><td>{{v.definition?.description}}<details><summary>约束</summary><pre>{{JSON.stringify(v.definition?.constraints,null,2)}}</pre></details></td><td><button v-if="v.status==='DRAFT'&&auth.permissions.includes('standard:write')" @click="edit(v)">编辑草稿</button><button v-if="v.status==='DRAFT'&&auth.permissions.includes('standard:publish')" :disabled="busy" @click="run(()=>publish(v))">发布</button></td></tr></tbody></table><label v-if="auth.permissions.includes('standard:publish')">发布或修改说明<textarea v-model="form.reason" maxlength="1000" placeholder="发布前填写说明"/></label><form v-if="auth.permissions.includes('standard:write')" @submit.prevent="run(saveVersion)"><h3>{{editing?'修改草稿':'新增版本'}}</h3><label v-if="!editing">版本号<input :value="form.versionNo" type="number" readonly></label><label>标准说明<textarea v-model="form.description" required maxlength="2000"/></label><ConstraintsForm :form="constraints"/><button :disabled="busy">保存草稿</button><button type="button" @click="newVersion">新版本</button></form><form v-if="auth.permissions.includes('standard:write')&&assets.length" @submit.prevent="run(binding)"><h3>关联发布版本与字段</h3><div class="columns"><label>标准版本<select v-model="bind.standardVersionId" required><option value="">请选择</option><option v-for="v in selected.versions.filter(v=>v.status==='PUBLISHED')" :key="v.id" :value="v.id">V{{v.versionNo}}</option></select></label><label>资产<select v-model="bind.assetId" required @change="run(assetChanged)"><option value="">请选择</option><option v-for="a in assets" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>字段<select v-model="bind.fieldId" required><option v-for="f in fields" :key="f.id" :value="f.id">{{f.displayName}} / {{f.fieldCode}}</option></select></label><label>关联说明<textarea v-model="bind.reason" required maxlength="1000"/></label></div><button :disabled="busy">追加关联</button></form></div></section></template>
